<script lang="ts">
 import {onMount,tick} from 'svelte';
 let {url,allowDownload=true}:{url:string;allowDownload?:boolean}=$props();
 let canvas:HTMLCanvasElement;let container:HTMLDivElement;let doc:any;let page=$state(1);let pages=$state(0);let scale=$state(1);let loading=$state(false);let error=$state('');let ready=$state(false);let rendering=false;let queued=false;let disposed=false;
 async function render(){if(!doc||disposed)return;if(rendering){queued=true;return;}rendering=true;queued=false;loading=true;error='';try{const p=await doc.getPage(page);if(disposed)return;const base=p.getViewport({scale:1});const available=Math.max(1,container.clientWidth-24);const viewport=p.getViewport({scale:Math.min(available/base.width,1.5)*scale});const dpr=window.devicePixelRatio||1;canvas.width=viewport.width*dpr;canvas.height=viewport.height*dpr;canvas.style.width=`${viewport.width}px`;canvas.style.height=`${viewport.height}px`;await p.render({canvasContext:canvas.getContext('2d'),viewport,transform:[dpr,0,0,dpr,0,0]}).promise;}catch{if(!disposed)error='Halaman tidak dapat ditampilkan. Silakan coba lagi.';}finally{loading=false;rendering=false;if(queued&&!disposed)void render();}}
 async function open(){if(!url){error='Dokumen PDF belum tersedia.';return;}loading=true;error='';try{if(doc)await doc.destroy();page=1;scale=1;const pdf=await import('pdfjs-dist');pdf.GlobalWorkerOptions.workerSrc=(await import('pdfjs-dist/build/pdf.worker.min.mjs?url')).default;doc=await pdf.getDocument(url).promise;pages=doc.numPages;ready=true;await tick();await render();}catch{error='Dokumen gagal dimuat. Periksa koneksi lalu coba lagi.';}finally{loading=false;}}
 async function move(delta:number){page=Math.max(1,Math.min(pages,page+delta));await render();}async function zoom(delta:number){scale=Math.max(.5,Math.min(2,scale+delta));await render();}
 onMount(()=>{let width=container.clientWidth;let timer:ReturnType<typeof setTimeout>|undefined;const resize=()=>{const next=container.clientWidth;if(next===width)return;width=next;clearTimeout(timer);timer=setTimeout(()=>{if(ready)void render();},120);};const observer=typeof ResizeObserver!=='undefined'?new ResizeObserver(resize):null;observer?.observe(container);if(!observer)window.addEventListener('resize',resize);return ()=>{disposed=true;observer?.disconnect();window.removeEventListener('resize',resize);clearTimeout(timer);void doc?.destroy();};});
</script>
<div class="reader"><div class="toolbar"><span>PEMBACA MAJALAH</span>{#if ready}<div><button onclick={()=>move(-1)} disabled={loading||page===1} aria-label="Halaman sebelumnya">←</button><span aria-live="polite">{page} / {pages}</span><button onclick={()=>move(1)} disabled={loading||page===pages} aria-label="Halaman berikutnya">→</button><button onclick={()=>zoom(-.25)} disabled={loading} aria-label="Perkecil">−</button><span>{Math.round(scale*100)}%</span><button onclick={()=>zoom(.25)} disabled={loading} aria-label="Perbesar">+</button></div>{/if}</div>{#if error}<p class="error" role="alert">{error}</p><button class="button light" onclick={open} disabled={loading}>Coba lagi ↻</button>{:else if !ready}<div class="start"><span>✳</span><h3>Luangkan waktu untuk sebuah cerita.</h3><p>Mulai membaca majalah langsung di browser.</p><button class="button" onclick={open} disabled={loading}>{loading?'Memuat dokumen…':'Mulai membaca ↗'}</button></div>{/if}{#if loading}<p role="status">Memuat halaman…</p>{/if}<div class="canvas-wrap" bind:this={container} class:inactive={!ready}><canvas bind:this={canvas} aria-label={`Halaman ${page} majalah`}></canvas></div>{#if url&&allowDownload}<a class="arrow-link" href={url} target="_blank" rel="noopener noreferrer" download>Unduh / buka PDF ↗</a>{/if}</div>
<style>.reader{border:1px solid #b8b9a9;background:#e7e7db;padding:20px}.toolbar{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center;font-size:10px;letter-spacing:.1em;border-bottom:1px solid #b8b9a9;padding-bottom:18px}.toolbar>div{display:flex;align-items:center;gap:12px}.toolbar button{border:1px solid #969d88;background:transparent;padding:7px 12px}.start{text-align:center;padding:60px 10px}.start>span{font-size:45px;color:#69785c}.start h3{margin-top:20px}.start p{font-size:12px}.canvas-wrap{overflow:auto;margin:20px 0;min-height:100px;max-height:85vh;text-align:center}.inactive{display:none}canvas{display:inline-block;background:white;max-width:none}.reader>.arrow-link{margin-top:15px}
.reader{min-width:0;max-width:100%}.toolbar>div{min-width:0;flex-wrap:wrap;gap:8px}.toolbar button{min-width:44px;min-height:44px}.toolbar>div>span{white-space:nowrap}.canvas-wrap{width:100%;overscroll-behavior:contain}.start .button{max-width:100%}
@media(max-width:480px){.reader{padding:14px}.toolbar{gap:14px}.toolbar>div{gap:6px}.toolbar button{padding-inline:10px}.start{padding:35px 0}.start h3{font-size:24px}}
</style>
